const hadiah = ["Stiker", "Gantungan kunci", "Kaos", "Voucher"];
function pilihAcak(daftar) {
  return daftar[Math.floor(Math.random() * daftar.length)];
}
const terpilih = pilihAcak(hadiah);
console.log(hadiah.includes(terpilih));
console.log(Math.floor(0.999 * hadiah.length));
console.log(Math.floor(0 * hadiah.length));

